1	// Shape tests for this pack's scheduled-task declarations.
2	//
3	// The Claudinite scheduler reads frequency / agent_model / expected_outcome from
4	// task.json — never from anywhere else — so a typo'd enum or a missing field means
5	// a task silently never fires. The canon's own `task-declaration-shape` check
6	// asserts that statically at author time; this asserts it by LOADING each
7	// declaration, which additionally parse-checks the JSON and its worker wiring.
8	// The contract's legal values are restated here as literals rather than imported
9	// from the mount, so this file never couples to the vendored canon.
10	
11	import { test } from "node:test";
12	import assert from "node:assert/strict";
13	import { existsSync, readFileSync } from "node:fs";
14	import { fileURLToPath } from "node:url";
15	import path from "node:path";
16	
17	import { terms as ticketTerms } from "./refresh-tickets/preconditions.mjs";
18	
19	const __dirname = path.dirname(fileURLToPath(import.meta.url));
20	const readDeclaration = (dir) => JSON.parse(readFileSync(path.join(__dirname, dir, "task.json"), "utf8"));
21	const refreshShows = readDeclaration("refresh-shows");
22	const refreshTickets = readDeclaration("refresh-tickets");
23	
24	const FREQUENCIES = ["daily", "weekly", "monthly", "manual"];
25	const MODELS = ["opus", "sonnet", "haiku", "none"];
26	const OUTCOMES = ["none", "open-pr", "merged-pr"];
27	
28	// Both scraping tasks are OFF, and `manual` is what carries that: a manual task
29	// has no occurrence for the scheduler to instantiate. Pinned here so turning one
30	// back on is a deliberate edit to this file rather than a token nobody re-reads.
31	// The declarative precondition is the ONLY gate mechanism — the `precondition`
32	// function form and its `precondition_signals` companion are retired
33	// (missingbulb/Claudinite#1617), so both are asserted ABSENT rather than present.
34	const DECLARED = [
35	  ["refresh-shows", refreshShows, "manual", ["none"], {}],
36	  ["refresh-tickets", refreshTickets, "manual", ["in-festival"], ticketTerms],
37	];
38	
39	for (const [dir, decl, frequency, preconditions, terms] of DECLARED) {
40	  test(`${dir} declares the full task contract`, () => {
41	    assert.equal(decl.id, dir, "the id must match the task's directory name");
42	    assert.equal(decl.frequency, frequency);
43	    assert.ok(FREQUENCIES.includes(decl.frequency), `illegal frequency ${decl.frequency}`);
44	    assert.ok(MODELS.includes(decl.agent_model), `illegal agent_model ${decl.agent_model}`);
45	    assert.ok(OUTCOMES.includes(decl.expected_outcome), `illegal expected_outcome ${decl.expected_outcome}`);
46	    assert.deepEqual(decl.preconditions, preconditions);
47	    assert.equal(typeof decl.agent_instructions, "string");
48	    // The retired form, asserted gone: a declaration carrying both is a contract
49	    // violation, and one carrying only the function stops running the moment the
50	    // mount drops support for it.
51	    assert.equal(decl.precondition, undefined);
52	    assert.equal(decl.precondition_signals, undefined);
53	    // Every named condition resolves — a built-in, or one this task's own
54	    // preconditions.mjs exports. An unknown term is a run failure, not a decline.
55	    for (const name of decl.preconditions) {
56	      assert.ok(name === "none" || name in terms, `${dir} names the unresolvable condition "${name}"`);
57	    }
58	  });
59	
60	  test(`${dir} is agentless and its worker exists`, () => {
61	    // Both of these tasks are deterministic ports of retired workflows: no agent,
62	    // so the contract requires the work to be a bounded code-work subprocess.
63	    assert.equal(decl.agent_model, "none");
64	    assert.equal(decl.code_work, "bash worker.sh");
65	    assert.ok(Number.isInteger(decl.code_work_timeout) && decl.code_work_timeout > 0);
66	    assert.ok(existsSync(path.join(__dirname, dir, "worker.sh")), "the declared worker must exist beside task.json");
67	  });
68	
69	  test(`${dir}'s own terms each return a verdict with a reason`, () => {
70	    for (const [name, term] of Object.entries(terms)) {
71	      const verdict = term.holds({}, { now: new Date("2026-08-15T11:49:00Z") });
72	      assert.equal(typeof verdict.holds, "boolean", `${name} answered no verdict`);
73	      assert.ok(verdict.reason.length > 0, "every verdict explains itself — it lands in the scheduler's job summary");
74	    }
75	  });
76	}
77	
78	// `none` IS "run whenever it is pulled": the empty precondition, whose trigger is
79	// the calendar or the work item somebody filed.
80	test("refresh-shows states no condition, so a pulled run always proceeds", () => {
81	  assert.deepEqual(refreshShows.preconditions, ["none"]);
82	});
83	
84	// The clock reaches the term from the ENGINE rather than the process, which is
85	// what makes the festival gate assertable at a chosen instant at all.
86	test("the in-festival term answers about the instant it is handed", () => {
87	  const at = (iso) => ticketTerms["in-festival"].holds({}, { now: new Date(iso) });
88	  assert.equal(at("2026-08-15T11:49:00Z").holds, true);
89	  assert.equal(at("2026-07-31T22:49:00Z").holds, false); // 23:49 BST on 31 July
90	  assert.equal(at("2026-07-31T23:49:00Z").holds, true);  // 00:49 BST on 1 August
91	  assert.ok(at("2026-09-15T11:49:00Z").reason.includes("outside the festival"));
92	});
93

