1	import { finding } from '../../../engine/checks/helpers/findings.mjs';
2	import { stripComments } from '../../../engine/checks/helpers/code-scanning.mjs';
3	import { ACCEPTED_FREQUENCIES, cadenceTermFor, cadenceOf } from '../../claudinite-tasks/calendar.mjs';
4	import { MODEL_FAMILIES } from '../../claudinite-tasks/model-map.mjs';
5	import {
6	  OUTCOMES, LEGACY_OUTCOMES, LEGACY_CEILINGS, OUTCOME_NO_PR, DEFAULT_AGENT_MODEL, descriptionProblem, normalizeTaskDeclaration,
7	  TRIGGERS, TRIGGER_SCHEDULE, TRIGGER_REQUEST,
8	} from '../../claudinite-tasks/task-contract.mjs';
9	import { validatePreconditions, termsMap, preconditionNeedsItem } from '../../claudinite-tasks/precondition-policy.mjs';
10	import { TASK_DECLARATION_PATH_RE, readDeclarationFields } from '../../claudinite-tasks/task-declaration-text.mjs';
11	
12	// Every scheduler task is a `tasks/<name>/task.json` carrying the declaration
13	// contract (docs/PRINCIPLES.md) with legal enum values. This
14	// asserts that shape statically at author time — the executor and scheduler
15	// validate the same contract at run time (task-contract.mjs), so an illegal
16	// condition/model/outcome, or a missing field, is caught here first.
17	//
18	// RELEVANCE FIRST (engine/checks/README.md): gated on a task declaration file
19	// existing, so the check is inert on any repo without tasks. Static text over the
20	// self-contained file — a `task.json` parsed whole — keyed off the canonical enum
21	// lists so the legal values never drift from the runtime validator.
22	
23	// The term names the task's own `preconditions.mjs` exports, read as text: the
24	// check runs over a file listing, not a module graph, so it recognises a
25	// task-local condition by the key that defines it. A term the file computes
26	// rather than spells is not found, and its declaration reads as unknown — which
27	// is the same "write it so a reader can see it" the literal rule above states.
28	// Read as TEXT, never imported: a check must not execute a member's own module. So
29	// each term is its name plus the one property of it a declaration can be wrong
30	// about — `needsItem`, which decides whether the term can be judged at a tick at
31	// all. Either quote style, because a member's file is its author's.
32	const TERM_NAME = /^ {2}['"]([^'"]+)['"]:/gm;
33	function siblingTerms(ctx, taskFile) {
34	  const text = ctx.read(taskFile.replace(/task\.json$/, 'preconditions.mjs'));
35	  if (text === null) return new Map();
36	  const body = stripComments(text);
37	  const start = body.indexOf('export const terms');
38	  if (start === -1) return new Map();
39	  const section = body.slice(start);
40	  const named = [...section.matchAll(TERM_NAME)];
41	  return termsMap(Object.fromEntries(named.map((m, i) => {
42	    const block = section.slice(m.index, named[i + 1]?.index ?? section.length);
43	    return [m[1], { signals: [], needsItem: /\bneedsItem\s*:\s*true\b/.test(block) }];
44	  })));
45	}
46	
47	const rule = {
48	  id: 'task-declaration-shape',
49	  severity: 'blocking',
50	  description: 'A tasks/<name>/task.json carries the task contract (id, description, preconditions, expected_outcome) with legal enum values and a well-formed precondition expression stating when the task runs; an agentic task names its worker file and bounds its run, and any code_work carries a timeout and stays task-local',
51	  doc: 'packs/claudinite-tasks/README.md',
52	  why: 'the scheduler run and executor read agent_model/expected_outcome/preconditions from this file, not the work item — an illegal or missing value means a task never fires, fires wrong, or writes past its ceiling',
53	
54	  run(ctx) {
55	    const out = [];
56	    for (const file of ctx.files.filter((f) => TASK_DECLARATION_PATH_RE.test(f))) {
57	      const text = ctx.read(file);
58	      if (text === null) continue;
59	      const flag = (what, fix) => out.push(finding(rule, { file, what, fix }));
60	      const advise = (what, fix) => out.push(finding(rule, { file, severity: 'advisory', what, fix }));
61	
62	      const decl = readDeclarationFields(text);
63	      if (decl.error) {
64	        flag(`is not a JSON object: ${decl.error}`, 'write one JSON object: { "id", "description", "preconditions", "expected_outcome", … }');
65	        continue;
66	      }
67	      const str = (key) => (typeof decl.scalar(key) === 'string' ? decl.scalar(key) : null);
68	      const hasNum = (...keys) => keys.some((key) => typeof decl.scalar(key) === 'number');
69	
70	      const enumField = (key, legal) => {
71	        const v = str(key);
72	        if (v === null) flag(`declares no "${key}"`, `add "${key}": one of ${legal.join(', ')}`);
73	        else if (!legal.includes(v)) flag(`"${key}" is "${v}", not a legal value`, `use one of: ${legal.join(', ')}`);
74	      };
75	      // `frequency` is retired (docs/PRINCIPLES.md): the cadence is a condition
76	      // in `preconditions`, and the door reads the field as exactly that term. ADVISORY
77	      // for the same reason as every rename below — the file keeps working, and the
78	      // nightly update rewrites a member's own — so what blocks is only a declaration
79	      // that states no "when" at all.
80	      const legacyFrequency = str('frequency');
81	      if (decl.has('frequency')) {
82	        const term = ACCEPTED_FREQUENCIES.includes(legacyFrequency) ? cadenceTermFor(legacyFrequency) : 'due:<daily|weekly|monthly>';
83	        advise('declares the retired field "frequency"', term === null
84	          ? 'drop the field, and a "none" beside it: "manual" meant no schedule, which a declaration says by stating no "preconditions" at all'
85	          : `write it as the first condition — "preconditions": [${JSON.stringify(term)}, …] — and drop a "none" beside it; the field reads as exactly that today`);
86	      }
87	      // `trigger` says whether the scheduler asks this task at every tick, and is
88	      // OPTIONAL for one convergence window (#1789) — absent, the door reads it off
89	      // the shape of the conditions, and `legacy-task-fields` is what says so. What
90	      // is checked here is a STATED one: the value, and the one pairing that cannot
91	      // work. A `schedule` task whose expression reads the ITEM has nothing to be
92	      // judged against at a tick — the scheduler's own ask carries no item — so the
93	      // term errors on every tick and the task's lane fills with failed runs rather
94	      // than ever declining.
95	      if (decl.has('trigger')) {
96	        const trigger = str('trigger');
97	        if (trigger === null || !TRIGGERS.includes(trigger)) {
98	          flag(`"trigger" is ${JSON.stringify(decl.scalar('trigger') ?? null)}, not a legal value`,
99	            `use one of: ${TRIGGERS.join(', ')} — "${TRIGGER_SCHEDULE}" is asked by the scheduler at every tick, "${TRIGGER_REQUEST}" runs only from an item somebody creates`);
100	        } else if (trigger === TRIGGER_SCHEDULE && decl.list('preconditions')
101	          && preconditionNeedsItem(decl.list('preconditions'), siblingTerms(ctx, file))) {
102	          flag('a "schedule" task states a condition that reads the item itself',
103	            `write "trigger": "${TRIGGER_REQUEST}" — a condition about one item can only be judged once an item exists, and the scheduler's ask at a tick has none, so this task would fail every tick instead of declining`);
104	        } else if (trigger === TRIGGER_REQUEST && cadenceOf(decl.list('preconditions'))) {
105	          // Inert, not merely redundant, which is why this blocks: nothing asks a
106	          // request task, so every occurrence of it is an item somebody created,
107	          // every such item carries `Woken:`, and a wake stands in for the cadence.
108	          // The term cannot decline a single run, and reads as though it could.
109	          flag('a "request" task states a cadence term',
110	            'drop the term — nothing asks this task, so every item of it is one somebody created and carries `Woken:`, which satisfies a cadence; the term can never decline a run, it only reads as though it limits the lever');
111	        }
112	      }
113	
114	      // agent_model is OPTIONAL: absent means no agent (task-defaults.mjs), so the
115	      // checks below judge the model the task will actually run at.
116	      const declaredModel = str('agent_model');
117	      if (decl.has('agent_model') && (declaredModel === null || !MODEL_FAMILIES.includes(declaredModel))) {
118	        flag(`"agent_model" is ${JSON.stringify(decl.scalar('agent_model') ?? null)}, not a legal value`, `use one of: ${MODEL_FAMILIES.join(', ')} — or drop it: a task with no agent_model runs no agent`);
119	      }
120	      const model = declaredModel ?? DEFAULT_AGENT_MODEL;
121	
122	      // expected_outcome takes the ceiling/policy split, with the retired
123	      // one-word ceilings an ADVISORY rename like the code-work names below:
124	      // the runtime normalizes them at the door forever, so a member's vendor
125	      // refresh must not turn its CI red over a declaration nobody edited.
126	      const outcome = str('expected_outcome');
127	      const hasMayAutomerge = decl.has('automerge');
128	      if (outcome === null) {
129	        flag('declares no "expected_outcome"', `add "expected_outcome": one of ${OUTCOMES.join(', ')}`);
130	      } else if (LEGACY_OUTCOMES[outcome] !== undefined) {
131	        advise(`declares the legacy outcome ceiling "${outcome}"`,
132	          `write the pair it normalizes to: "expected_outcome": "fresh_pr", "automerge": "${LEGACY_OUTCOMES[outcome]}" — and consider a narrower policy than "${LEGACY_OUTCOMES[outcome]}" (a list of diff classes, e.g. ["comment-only-changes"])`);
133	      } else if (LEGACY_CEILINGS[outcome] !== undefined) {
134	        advise(`declares the legacy outcome ceiling "${outcome}"`,
135	          `write the word it became: "expected_outcome": "${LEGACY_CEILINGS[outcome]}" — the same behaviour, in the vocabulary that also offers amend_existing_or_create_new_pr and supersede_existing_pr`);
136	      } else if (!OUTCOMES.includes(outcome)) {
137	        flag(`"expected_outcome" is "${outcome}", not a legal value`, `use one of: ${OUTCOMES.join(', ')}`);
138	      }
139	      // Judged on the word the door normalizes to, so the retired `none` gets the
140	      // same verdict as today's spelling beside its rename advisory.
141	      if (outcome !== null && (LEGACY_CEILINGS[outcome] ?? outcome) === OUTCOME_NO_PR && hasMayAutomerge) {
142	        flag(`a "${OUTCOME_NO_PR}" task declares "automerge"`, 'drop it — a task that opens no pull request has nothing to merge; or set expected_outcome: "fresh_pr"');
143	      }
144	
145	      if (str('id') === null) flag('declares no string "id"', 'add "id": the task name (matching its directory)');
146	      // ADVISORY when absent — a member's converted task carries none, and its
147	      // vendor refresh must not go red over it — and blocking when declared badly.
148	      if (!decl.has('description')) {
149	        advise('declares no "description"', 'add "description": up to fifty words on what the task does or why it exists — not what the other fields already say');
150	      } else {
151	        const problem = descriptionProblem(decl.scalar('description'));
152	        if (problem) flag(problem.what, problem.fix);
153	      }
154	      // agent_instructions is required only for an agentic task (agent_model !==
155	      // 'none') — that's the worker file the agent reads, and it has no default. A
156	      // `none` task runs no agent, so the field is not applicable.
157	      if (model !== 'none' && str('agent_instructions') === null) {
158	        flag('an agentic task (agent_model !== "none") declares no string "agent_instructions"', 'add "agent_instructions": the worker file beside the declaration (e.g. "task.md")');
159	      }
160	      // `preconditions` is the only gate a task declares (#1617). The retired
161	      // spelling is flagged by NAME rather than merely going unrecognised, so a
162	      // declaration carrying it is told what replaced it instead of reading as a
163	      // task that simply forgot its gate.
164	      if (decl.has('precondition')) {
165	        flag('declares "precondition", which is retired', 'move the gate into "preconditions" — a built-in condition, or a term this task\'s preconditions.mjs exports');
166	      }
167	      if (decl.has('precondition_signals')) {
168	        flag('declares "precondition_signals", which is retired', 'drop it — the signal union is derived from the conditions, each of which names what it reads');
169	      }
170	      // What must hold for a run, and OPTIONAL: a declaration stating none requires
171	      // nothing, and every occurrence of it runs. A retired `frequency` reads exactly
172	      // as the door reads it, cadence term first and a `none` beside it dropped — and
173	      // the expression is judged term by term.
174	      if (decl.has('preconditions') || decl.has('frequency')) {
175	        // Deliberately strict: a declaration whose trigger is computed cannot be
176	        // audited by anyone reading it, which is the whole reason the field is data.
177	        const stated = decl.has('preconditions') ? decl.list('preconditions') : [];
178	        if (stated === null) {
179	          flag('"preconditions" is not a literal list of condition strings', 'write it as a literal, e.g. "preconditions": ["due:daily", "substantive-change"] — a computed expression is unreadable to this check and to the next person');
180	        } else {
181	          const expression = normalizeTaskDeclaration({ preconditions: stated, ...(decl.has('frequency') ? { frequency: legacyFrequency } : {}) }).preconditions;
182	          for (const problem of validatePreconditions(expression, siblingTerms(ctx, file))) flag(problem.what, problem.fix);
183	        }
184	      }
185	
186	      // The code-work/timeout guards (docs/PRINCIPLES.md). TWO generations of
187	      // legacy field names still satisfy the contract — the loader normalizes both —
188	      // but each earns its own rename finding so the fleet converges on the
189	      // canonical names.
190	      const LEGACY_CODE_WORK = [
191	        { field: 'agent_preprocessing', timeout: 'agent_preprocessing_timeout' },
192	        { field: 'prework', timeout: 'prework_timeout' },
193	      ];
194	      const legacyDeclared = LEGACY_CODE_WORK.filter(({ field }) => str(field) !== null);
195	      const hasCodeWork = str('code_work') !== null || legacyDeclared.length > 0;
196	      for (const { field, timeout } of legacyDeclared) {
197	        // ADVISORY, deliberately, on a blocking rule: the legacy names still
198	        // satisfy the runtime contract (normalized at load), and a member's
199	        // vendor refresh must not turn its CI red over files nothing has renamed
200	        // yet. This finding IS the durable driver of the rename — it names the
201	        // exact edit and does not age out, which is why neither rename ships a
202	        // migration note.
203	        advise(`declares code_work under the legacy name "${field}"`,
204	          `rename "${field}" → "code_work" and "${timeout}" → "code_work_timeout" (the two phases of task execution are code-work, then agentic-work — neither is named for the other)`);
205	      }
206	      // The ordering field's rename. ADVISORY for the same reason as the code-work rename above:
207	      // the runtime normalizes it at the door, so a member's own task file keeps working and its
208	      // CI must not go red over a declaration nobody has edited. Worth making because the bare
209	      // preposition invited reading the field as a time — it is not one; it names task ids, and
210	      // what it steers is when the item is scheduled onto an executor.
211	      // The secrets field's rename, advisory for the same reason: the door normalizes
212	      // it, and only the name changed — the secrets are the code-work phase's.
213	      if (decl.has('required_secrets')) {
214	        advise('declares its secrets under the legacy name "required_secrets"',
215	          'rename "required_secrets" to "code_work_required_secrets" — the secrets are what the code-work phase, the one that runs Action-side, is handed');
216	      }
217	      if (decl.has('after')) {
218	        advise('declares its ordering under the legacy name "after"',
219	          'rename "after" to "schedule_after" (it names task ids, not a time — what it steers is when this item is scheduled onto an executor)');
220	      }
221	      // `session_scope` lost its last reader with the slot scheduler (#974): the
222	      // queue routes a hand-off by `invocation_endpoint`, and nothing anywhere
223	      // asks a task what its scope is. ADVISORY, like the code-work rename above and
224	      // for the same reason — the field still VALIDATES, so a member's vendor
225	      // refresh must not turn its CI red over a declaration nobody has edited yet;
226	      // this only keeps the dead field visible until it is dropped.
227	      if (str('session_scope') !== null) {
228	        advise('declares "session_scope", which nothing reads',
229	          'drop it — reach is a property of which endpoint the hand-off calls, so a task needing wider access declares "invocation_endpoint": <a key in the repo\'s taskScheduler.agenticTaskInvocationEndpoints> instead');
